gb7U(){return"\u0412\u043e\u0434\u0430\u0447\u0438 \u0441 \u043f\u0440\u043e\u0444\u0438\u043b \u0432 Stavia \u043f\u043e\u043a\u0430\u0437\u0432\u0430\u0442 \u201e\u041c\u043e\u044f\u0442 \u043a\u043e\u0434\u201c \u043d\u0430 \u0432\u0445\u043e\u0434\u0430, \u043f\u043e\u0442\u0432\u044a\u0440\u0436\u0434\u0430\u0432\u0430\u0442 \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430 \u0441\u0438 \u0438 \u043f\u043b\u0430\u0449\u0430\u0442 \u043f\u0440\u0438 \u0438\u0437\u043b\u0438\u0437\u0430\u043d\u0435. \u0421\u043b\u0443\u0436\u0438\u0442\u0435\u043b\u044f\u0442 \u0433\u043e \u0441\u043a\u0430\u043d\u0438\u0440\u0430 \u0432\u044a\u0432 \u201e\u0412\u0445\u043e\u0434\u201c."},
gbaW(){return"\u0412\u043b\u0438\u0437\u0430\u043d\u0435 \u0441 \u201e\u041c\u043e\u044f\u0442 \u043a\u043e\u0434\u201c"},
asI(a){return a+" \u0435 \u043d\u043e\u0432 \u0437\u0430 Stavia. \u041f\u043e\u0442\u0432\u044a\u0440\u0434\u0438, \u0447\u0435 \u0441\u0438 \u043d\u0430 18 \u0438\u043b\u0438 \u043f\u043e\u0432\u0435\u0447\u0435, \u0438 \u043f\u0440\u043e\u0444\u0438\u043b\u044a\u0442 \u0435 \u0433\u043e\u0442\u043e\u0432; \u0438\u043c\u0435\u0442\u043e \u0435 \u043f\u043e \u0436\u0435\u043b\u0430\u043d\u0438\u0435."},
gasJ(){return"\u0418\u043c\u0435\u0442\u043e \u0442\u0438 (\u043f\u043e \u0436\u0435\u043b\u0430\u043d\u0438\u0435)"},
gasK(){return"\u0417\u0430 \u043f\u043e\u0437\u0434\u0440\u0430\u0432. \u041e\u0431\u0435\u043a\u0442\u044a\u0442 \u0432\u0438\u0436\u0434\u0430 \u043d\u043e\u043c\u0435\u0440\u0430 \u043d\u0430 \u043a\u043e\u043b\u0430\u0442\u0430 \u0442\u0438 \u0438 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043e\u0442\u043e \u0442\u0438 \u0438\u043c\u0435, \u0430\u043a\u043e \u0433\u043e \u0434\u0430\u0434\u0435\u0448. \u0412 \u0442\u0435\u0441\u0442\u043e\u0432\u0438\u0442\u0435 \u0441\u0440\u0435\u0434\u0438 \u043f\u043e\u043b\u0437\u0432\u0430\u0439 \u0438\u0437\u043c\u0438\u0441\u043b\u0435\u043d\u043e \u0438\u043c\u0435."},
gbhW(){return"\u041f\u0440\u043e\u0444\u0438\u043b\u044a\u0442 \u0442\u0438 \u0435 \u0433\u043e\u0442\u043e\u0432"},
gbhV(){return"\u041e\u0449\u0435 \u0434\u0432\u0435 \u043d\u0435\u0449\u0430 \u0438 \u043c\u043e\u0436\u0435\u0448 \u0434\u0430 \u043f\u0430\u0440\u043a\u0438\u0440\u0430\u0448: \u043a\u043e\u043b\u0430\u0442\u0430 \u0438 \u043d\u0430\u0447\u0438\u043d\u044a\u0442 \u043d\u0430 \u043f\u043b\u0430\u0449\u0430\u043d\u0435. \u0418 \u0434\u0432\u0435\u0442\u0435 \u043c\u043e\u0433\u0430\u0442 \u0434\u0430 \u043f\u043e\u0447\u0430\u043a\u0430\u0442."},
bi_(a){return"\u0422\u0435\u043b\u0435\u0444\u043e\u043d "+a},
gbhY(){return"\u041a\u043e\u043b\u0430\u0442\u0430 \u0442\u0438"},
