bcK(a){return"\u041d\u0430 \u043c\u044f\u0441\u0442\u043e: "+a+", \u043f\u0440\u0438 \u0438\u0437\u043b\u0438\u0437\u0430\u043d\u0435"},
gbcH(){return"\u041f\u043b\u0430\u0449\u0430\u0448 \u043d\u0430 \u0441\u043b\u0443\u0436\u0438\u0442\u0435\u043b\u044f \u043f\u0440\u0438 \u0438\u0437\u043b\u0438\u0437\u0430\u043d\u0435, \u0442\u043e\u0447\u043d\u043e \u0437\u0430 \u0432\u0440\u0435\u043c\u0435\u0442\u043e, \u043f\u043e \u0446\u0435\u043d\u0430\u0442\u0430 \u043d\u0430 \u043c\u044f\u0441\u0442\u043e\u0442\u043e. Stavia \u043d\u0435 \u0442\u0430\u043a\u0441\u0443\u0432\u0430 \u043a\u0430\u0440\u0442\u0430\u0442\u0430 \u0442\u0438."},
anw(a){return"\u041f\u043b\u0430\u0449\u0430\u0448 \u043d\u0430 \u043c\u044f\u0441\u0442\u043e \u043f\u0440\u0438 \u0438\u0437\u043b\u0438\u0437\u0430\u043d\u0435: "+a+"."},
bp0(a,b){return"\u041f\u043b\u0430\u0442\u0435\u043d\u043e \u043d\u0430 \u043c\u044f\u0441\u0442\u043e \xb7 "+a+" \xb7 "+b},
aZw(a){return"\u0417\u0430 \u043f\u043b\u0430\u0449\u0430\u043d\u0435 \u043d\u0430 \u043c\u044f\u0441\u0442\u043e: "+a},
gb__(){return"\u041f\u043b\u0430\u0442\u0435\u043d\u043e \u0432 \u0431\u0440\u043e\u0439 \xb7 \u043f\u0443\u0441\u043d\u0438 \u0434\u0430 \u0438\u0437\u043b\u0435\u0437\u0435"},
