gasf(){return"\u041a\u043e\u043d\u0437\u043e\u043b\u0430\u0442\u0430 \u043d\u0430 \u0435\u043a\u0438\u043f\u0430 \u043d\u0430 Stavia."},
gase(){return"\u0418\u043c\u0435\u0439\u043b, \u043f\u0430\u0440\u043e\u043b\u0430 \u0438 \u0441\u043b\u0435\u0434 \u0442\u044f\u0445 \u0437\u0430\u0434\u044a\u043b\u0436\u0438\u0442\u0435\u043b\u0435\u043d \u0432\u0442\u043e\u0440\u0438 \u0444\u0430\u043a\u0442\u043e\u0440. \u0412\u0441\u044f\u043a\u043e \u043e\u0442\u0432\u0430\u0440\u044f\u043d\u0435 \u043d\u0430 \u0434\u0430\u043d\u043d\u0438 \u043d\u0430 \u0447\u043e\u0432\u0435\u043a \u0441\u0435 \u0437\u0430\u043f\u0438\u0441\u0432\u0430."},
